def print_rank_0(message, debug=False, force=False):
    if dist.get_rank() == 0 and (debug or force):
        print(message)


def _get_legacy_autocast_decorators(device_type):
    legacy_amp = getattr(getattr(torch, device_type, None), 'amp', None)
    custom_fwd = getattr(legacy_amp, 'custom_fwd', None)
    custom_bwd = getattr(legacy_amp, 'custom_bwd', None)
    if custom_fwd is not None and custom_bwd is not None:
        return custom_fwd, custom_bwd
    return noop_decorator, noop_decorator


def _get_autocast_decorators():
    amp = getattr(torch, 'amp', None)
    custom_fwd = getattr(amp, 'custom_fwd', None)
    custom_bwd = getattr(amp, 'custom_bwd', None)
    if custom_fwd is not None and custom_bwd is not None:
        device_type = get_accelerator().device_name()
        return functools.partial(custom_fwd, device_type=device_type), functools.partial(custom_bwd,
                                                                                         device_type=device_type)
    return _get_legacy_autocast_decorators(get_accelerator().device_name())


autocast_custom_fwd, autocast_custom_bwd = _get_autocast_decorators()


def _is_autocast_enabled(device_type):
    try:
        return torch.is_autocast_enabled(device_type)
    except TypeError:
        legacy_getter = getattr(torch, f'is_autocast_{device_type}_enabled', None)
        if legacy_getter is not None:
            return legacy_getter()
        return torch.is_autocast_enabled()


def _get_autocast_dtype(device_type):
    try:
        return torch.get_autocast_dtype(device_type)
    except TypeError:
        legacy_getter = getattr(torch, f'get_autocast_{device_type}_dtype', None)
        if legacy_getter is not None:
            return legacy_getter()
        return None


def _get_autocast_device_type(tensor):
    # Autocast state is per device type and only applies to ops on tensors of that type, so it
    # must follow the operands (e.g. CPU autocast on a CUDA machine), not the accelerator.
    device_type = tensor.device.type
    is_autocast_available = getattr(torch.amp, 'is_autocast_available', None)
    if is_autocast_available is not None and not is_autocast_available(device_type):
        return get_accelerator().device_name()
    return device_type


class LinearFunctionForZeroStage3(torch.autograd.Function):

    generate_vmap_rule = True

    @staticmethod
    # bias is an optional argument
    def forward(input, weight, bias=None):

        if input.dim() == 2 and bias is not None:
            # fused op is marginally faster
            ret = torch.addmm(bias, input, weight.t())
        else:
            output = input.matmul(weight.t())
            if bias is not None:
                output += bias
            ret = output

        return ret

    @staticmethod
    def setup_context(ctx, inputs, output):
        device_type = _get_autocast_device_type(inputs[0])
        ctx._autocast_device_type = device_type
        ctx._dtype = _get_autocast_dtype(device_type)
        ctx._fwd_used_autocast = _is_autocast_enabled(device_type)
        input, weight, bias = inputs[0], inputs[1], inputs[2] if len(inputs) > 2 else None
        ctx.save_for_backward(input, weight, bias)

    # This function has only a single output, so it gets only one gradient
    @staticmethod
    def backward(ctx, grad_output):
        # Match @custom_bwd semantics: always run backward under the same
        # autocast state as forward — including explicitly disabling autocast
        # when forward did not use it, to guard against outer autocast regions.
        with torch.autocast(device_type=ctx._autocast_device_type, enabled=ctx._fwd_used_autocast, dtype=ctx._dtype):
            input, weight, bias = ctx.saved_tensors

            grad_input = grad_weight = grad_bias = None
            weight_was_partitioned = (is_zero_param(weight)
                                      and getattr(weight.ds_status, "name", None) == "NOT_AVAILABLE")
            if weight_was_partitioned:
                weight.all_gather()

            try:
                dim = grad_output.dim()
                if ctx.needs_input_grad[0]:
                    grad_input = grad_output.matmul(weight)
                if ctx.needs_input_grad[1]:
                    if dim > 2:
                        grad_weight = grad_output.reshape(-1, grad_output.shape[-1]).t().matmul(
                            input.reshape(-1, input.shape[-1]))
                    elif dim == 1:
                        grad_weight = grad_output.unsqueeze(-1) * input.unsqueeze(0)
                    else:
                        grad_weight = grad_output.t().matmul(input)
                if bias is not None and ctx.needs_input_grad[2]:
                    if dim > 2:
                        grad_bias = grad_output.sum([i for i in range(dim - 1)])
                    elif dim == 1:
                        grad_bias = grad_output
                    else:
                        grad_bias = grad_output.sum(0)
                return grad_input, grad_weight, grad_bias
            finally:
                if weight_was_partitioned:
                    weight.partition()


def zero3_linear_wrap(input, weight, bias=None):
    return LinearFunctionForZeroStage3.apply(input, weight, bias)


class LinearModuleForZeroStage3(Module):
    r"""Applies a linear transformation to the incoming data: :math:`y = xA^T + b`.
    The weights are pre-transposed and stored as A^T instead of transposing during each
    forward. Memory savings proportional to the parameter size.

    Args:
        in_features: size of each input sample
        out_features: size of each output sample
        bias: If set to ``False``, the layer will not learn an additive bias.
            Default: ``True``

    Shape:
        - Input: :math:`(N, *, H_{in})` where :math:`*` means any number of
          additional dimensions and :math:`H_{in} = \text{in\_features}`
        - Output: :math:`(N, *, H_{out})` where all but the last dimension
          are the same shape as the input and :math:`H_{out} = \text{out\_features}`.

    Attributes:
        weight: the learnable weights of the module of shape
            :math:`(\text{out\_features}, \text{in\_features})`. The values are
            initialized from :math:`\mathcal{U}(-\sqrt{k}, \sqrt{k})`, where
            :math:`k = \frac{1}{\text{in\_features}}`
        bias:   the learnable bias of the module of shape :math:`(\text{out\_features})`.
                If :attr:`bias` is ``True``, the values are initialized from
                :math:`\mathcal{U}(-\sqrt{k}, \sqrt{k})` where
                :math:`k = \frac{1}{\text{in\_features}}`

    Examples::

        >>> m = nn.Linear(20, 30)
        >>> input = torch.randn(128, 20)
        >>> output = m(input)
        >>> print(output.size())
        torch.Size([128, 30])
    """
    __constants__ = ['in_features', 'out_features']
    in_features: int
    out_features: int
    weight: Tensor

    def __init__(self, in_features: int, out_features: int, bias: bool = True) -> None:
        super(LinearModuleForZeroStage3, self).__init__()
        print("Building ZeRO module")
        self.in_features = in_features
        self.out_features = out_features
        self.weight = Parameter(torch.Tensor(out_features, in_features))
        if bias:
            self.bias = Parameter(torch.Tensor(out_features))
        else:
            self.register_parameter('bias', None)
        self.reset_parameters()

    def reset_parameters(self) -> None:
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            init.uniform_(self.bias, -bound, bound)

    def forward(self, input: Tensor) -> Tensor:
        return LinearFunctionForZeroStage3.apply(input, self.weight, self.bias)

    def extra_repr(self) -> str:
        return 'in_features={}, out_features={}, bias={}'.format(self.in_features, self.out_features, self.bias
                                                                 is not None)

    def partition_gradients(param_list=None, partition_buffers=None, hierarchy=0, accumulate=False):
        cls = param
        print_rank_0(
            f"{'--'*hierarchy}----Partitioning param gradient with id {debug_param2name_id_shape_device(cls)}")
        if param_list is None:
            param_list = [cls]
            if isinstance(partition_buffers, torch.Tensor):
                partition_buffers = [partition_buffers]

        self._partition_gradients(param_list, partition_buffers=partition_buffers, accumulate=accumulate)

    def aligned_size():
        return self._aligned_size(param)

    def padding_size():
        return self._padding_size(param)

    def partition_numel():
        return self._partition_numel(param)

    def item_override():
        param.all_gather()
        return param._orig_item()

    def ds_summary(slf: torch.Tensor, use_debug_name: bool = False) -> dict:
        return {
            "id": debug_param2name_id(slf) if use_debug_name else slf.ds_id,
            "status": slf.ds_status.name,
            "numel": slf.numel(),
            "ds_numel": slf.ds_numel,
            "shape": tuple(slf.shape),
            "ds_shape": tuple(slf.ds_shape),
            "requires_grad": slf.requires_grad,
            "grad_shape": tuple(slf.grad.shape) if slf.grad is not None else None,
            "persist": slf.ds_persist,
            "active_sub_modules": slf.ds_active_sub_modules,
            "ds_tensor.shape": slf.ds_tensor.shape if slf.ds_tensor is not None else None
        }

    def convert_to_zero_parameters(param_list):
        self._convert_to_zero_parameters(param_list)

    def allgather_before(func: Callable) -> Callable:

        def wrapped(*args, **kwargs):
            param.all_gather()
            return func(*args, **kwargs)

        return wrapped

    # Collectives for gathering and partitioning parameters
    param.all_gather = all_gather
    param.all_gather_coalesced = all_gather_coalesced
    param.partition = partition

    # Collective for averaging gradients
    param.reduce_gradients_at_owner = reduce_gradients_at_owner
    param.partition_gradients = partition_gradients

    # Partitioning size utilities
    param.aligned_size = aligned_size
    param.padding_size = padding_size
    param.partition_numel = partition_numel
    param.ds_summary = types.MethodType(ds_summary, param)

    param.item = allgather_before(param.item)

    param.convert_to_zero_parameters = convert_to_zero_parameters

def _aligned_size(self, param):
    return param.ds_numel + self._padding_size(param)

def _padding_size(self, param):
    partition_world_size = self._partition_world_size(param)
    remainder = param.ds_numel % partition_world_size
    return (partition_world_size - remainder) if remainder else 0

def _partition_numel(self, param):
    return param.ds_tensor.ds_numel

def _partition_world_size(self, param):
    return dist.get_world_size(group=self.get_partition_dp_group(param))

def _partition_rank(self, param):
    return dist.get_rank(group=self.get_partition_dp_group(param))

def _ensure_availability_of_partitioned_params(self, params):
    swap_in_list = []
    swap_in_flight = []
    for param in params:
        if param.ds_tensor.status == PartitionedParamStatus.NOT_AVAILABLE:
            assert param.ds_tensor.final_location == OffloadDeviceEnum.nvme and param.ds_status == ZeroParamStatus.NOT_AVAILABLE
            swap_in_list.append(param)
        if param.ds_tensor.status == PartitionedParamStatus.INFLIGHT:
            assert param.ds_tensor.final_location == OffloadDeviceEnum.nvme and param.ds_status == ZeroParamStatus.NOT_AVAILABLE
            swap_in_flight.append(param)
    if len(swap_in_list) > 0:
        swap_in_list[0].nvme_swapper.swap_in(swap_in_list, async_op=False)
    elif len(swap_in_flight) > 0:
        swap_in_flight[0].nvme_swapper.synchronize_reads()

@instrument_w_nvtx
def _all_gather(self, param_list, async_op=False, hierarchy=None):

    # fetches from nvme if the partition is not available and in nvme
    self._ensure_availability_of_partitioned_params(param_list)

    handles = []
    all_gather_list = []
    for param in param_list:
        if param.ds_status == ZeroParamStatus.NOT_AVAILABLE:
            if async_op:
                handle = self._allgather_param(param, async_op=async_op, hierarchy=hierarchy)
                param.ds_status = ZeroParamStatus.INFLIGHT  # if async_op else ZeroParamStatus.AVAILABLE
                handles.append(handle)
            else:
                all_gather_list.append(param)
    # note: param_list may contain params that are already in flight / aviailable. So we need to use all_gather_list
    if not async_op:
        all_gather_by_group = {}
        for param in all_gather_list:
            all_gather_by_group.setdefault(id(self.get_partition_dp_group(param)), []).append(param)
        for group_params in all_gather_by_group.values():
            if self.allgather_sequential or len(group_params) == 1:
                ret_value = self._allgather_params_sequential(group_params, hierarchy=hierarchy)
            else:
                all_gather_quantize_list = []
                all_gather_nonquantize_list = []
                for param in group_params:
                    if hasattr(param.ds_tensor,
                               "ds_quant_scale") or (hasattr(param, "ds_secondary_tensor")
                                                     and hasattr(param.ds_secondary_tensor, "ds_quant_scale")):
                        all_gather_quantize_list.append(param)
                    else:
                        all_gather_nonquantize_list.append(param)
                # _allgather_params_coalesced always return None
                self._allgather_params_coalesced(all_gather_nonquantize_list, hierarchy, quantize=False)
                self._allgather_params_coalesced(all_gather_quantize_list, hierarchy, quantize=True)
        for param in all_gather_list:
            param.ds_status = ZeroParamStatus.AVAILABLE
        return None

    return handles

def _partition(self, param_list, force=False, has_been_updated=False, free_data=True):
    for param in param_list:
        print_rank_0(f"Before Partitioning Param {param.ds_id}", force=False)
        if self.zero_param_process_group is not None:
            self._partition_param_sec(param, has_been_updated=has_been_updated)
        self._partition_param(param, has_been_updated=has_been_updated, free_data=free_data)

        param.ds_status = ZeroParamStatus.NOT_AVAILABLE
